  "chunks": [
    {
      "chunk_type": "isnad",
      "arabic_text": "يُونُسُ عَنْ بَعْضِ أَصْحَابِهِ عَنْ أَبِي عَبْدِ اللَّهِ عَلَيْهِ السَّلَامُ",
      "translations": {
        "en": "Yūnus, from some of his companions, from Abī ʿAbdillāh عليه السلام."
      }
    },
    {
      "chunk_type": "body",
      "arabic_text": "أَنَّ امْرَأَةً نَذَرَتْ أَنْ تُقَادَ مَزْمُومَةً، فَدَفَعَهَا بَعِيرٌ فَخَرَمَ أَنْفَهَا، فَأَتَتْ أَمِيرَ الْمُؤْمِنِينَ عَلَيْهِ السَّلَامُ تُخَاصِمُ صَاحِبَ الْبَعِيرِ، فَأَبْطَلَهُ وَقَالَ: «إِنَّمَا نَذَرْتِ، لَيْسَ عَلَيْكِ ذَاكِ»."
      "translations": {
        "en": "A woman had made a vow that she would be led by a nose-rope. Then a camel pushed her and tore her nose, so she came to Amīr al-Muʾminīn عليه السلام disputing with the owner of the camel. He nullified the claim and said: “You only made a vow; that is not binding upon you.”"
      }
    }
  ],
  "translations": {
    "en": {
      "summary": "This hadith reports a legal judgment by Amīr al-Muʾminīn عليه السلام regarding a woman who was injured in connection with a vow she had made. The ruling indicates that her vow did not impose liability in the manner she claimed, making the report relevant to questions of legal responsibility and harm.",
      "seo_question": "What did Amīr al-Muʾminīn عليه السلام rule about injury connected to a vow?",
      "key_terms": {
        "نَذَرَتْ": "she made a vow",
        "مَزْمُومَةً": "being led by a nose-rope or rein",
        "بَعِيرٌ": "a camel",
        "فَخَرَمَ": "then it tore or pierced",
        "أَنْفَهَا": "her nose",
        "تُخَاصِمُ": "she was disputing or bringing a complaint",
        "فَأَبْطَلَهُ": "so he nullified it",
        "ذَاكِ": "that matter or obligation"
      }
    }
  },
